## Recommended Mitigation Steps
Includes a `require` statement to check that the Ether sent matches the `_ethMarginBalance` expected, preventing any unintended loss of Ether.
```solidity
function openCdpWithEth(
    uint256 _debt,
    bytes32 _upperHint,
    bytes32 _lowerHint,
    uint256 _stEthLoanAmount,
    uint256 _ethMarginBalance,
    uint256 _stEthDepositAmount,
    bytes calldata _positionManagerPermit,
    TradeData calldata _tradeData
) external payable returns (bytes32 cdpId) {
    require(msg.value == _ethMarginBalance, "EbtcLeverageZapRouter: Incorrect Ether sent");
    uint256 _collVal = _convertRawEthToStETH(_ethMarginBalance);
    cdpId = _openCdp(
        _debt,
        _upperHint,
        _lowerHint,
        _stEthLoanAmount,
        _collVal,
        _stEthDepositAmount,
        _positionManagerPermit,
        _tradeData
    );
    emit ZapOperationEthVariant(
        cdpId,
        EthVariantZapOperationType.OpenCdp,
        true,
        NATIVE_ETH_ADDRESS,
        _ethMarginBalance,
        _collVal,
        msg.sender
    );
}
```
